function(container, apiUrl, tables) {
  let stores = [];
  let products = [];
  let categories = [];
  let orderItems = [];
  let currentPredictions = {};

  // 初期データの設定
  if (tables[1] && tables[1].records) stores = tables[1].records;
  if (tables[2] && tables[2].records) products = tables[2].records;

  // カテゴリ一覧を商品から抽出
  const categoryIds = [...new Set(products.map(p => p.商品カテゴリID).filter(Boolean))];
  categories = categoryIds.map(id => ({ id, name: `カテゴリ${id.slice(-4)}` }));

  // 今日の日付を発注日にセット
  const today = new Date().toISOString().split('T')[0];
  container.querySelector('#order-date').value = today;

  // 店舗選択肢を設定
  function renderStoreOptions() {
    const storeSelect = container.querySelector('#store-select');
    storeSelect.innerHTML = '<option value="">店舗を選択してください</option>' +
      stores.map(store => `<option value="${store.店舗ID}">${store.店舗名}</option>`).join('');
  }

  // カテゴリ選択肢を設定
  function renderCategoryOptions() {
    const categorySelect = container.querySelector('#category-select');
    categorySelect.innerHTML = '<option value="">全カテゴリ</option>' +
      categories.map(cat => `<option value="${cat.id}">${cat.name}</option>`).join('');
  }

  // 商品一覧を描画
  function renderProductList(filteredProducts = products) {
    const tbody = container.querySelector('#product-list');
    tbody.innerHTML = filteredProducts.map(product => {
      const prediction = currentPredictions[product.商品ID] || 0;
      return `
        <tr data-id="${product.商品ID}">
          <td style="color: var(--text);">${product.商品コード || ''}</td>
          <td style="color: var(--text);">${product.商品名 || ''}</td>
          <td style="color: var(--text);">${product.単価 || 0}円</td>
          <td style="color: var(--text);">100</td>
          <td style="color: var(--text);"><span class="ai-prediction" data-product-id="${product.商品ID}">${prediction}</span></td>
          <td>
            <input type="number" class="input manual-quantity" data-product-id="${product.商品ID}" 
                   style="width: 80px;" min="0" value="${prediction}">
          </td>
          <td>
            <button class="action-btn secondary add-to-order" data-product-id="${product.商品ID}">追加</button>
          </td>
        </tr>
      `;
    }).join('');
  }

  // 発注商品一覧を描画
  function renderOrderItems() {
    const tbody = container.querySelector('#order-items-list');
    tbody.innerHTML = orderItems.map(item => `
      <tr data-id="${item.商品ID}">
        <td style="color: var(--text);">${item.商品コード}</td>
        <td style="color: var(--text);">${item.商品名}</td>
        <td style="color: var(--text);">${item.発注数量}</td>
        <td style="color: var(--text);">${item.単価}円</td>
        <td style="color: var(--text);">${item.発注数量 * item.単価}円</td>
        <td>
          <button class="action-btn secondary remove-from-order" data-product-id="${item.商品ID}">削除</button>
        </td>
      </tr>
    `).join('');

    // 発注総額を更新
    const totalAmount = orderItems.reduce((sum, item) => sum + (item.発注数量 * item.単価), 0);
    container.querySelector('#total-amount').textContent = totalAmount.toLocaleString();
  }

  // エラーメッセージ表示
  function showError(message) {
    const errorDiv = container.querySelector('#error-message');
    errorDiv.textContent = message;
    errorDiv.classList.remove('hidden');
    setTimeout(() => errorDiv.classList.add('hidden'), 5000);
  }

  // AI予測数量を取得（模擬）
  async function fetchAIPredictions(storeId) {
    // 実際のAI予測APIを呼ぶ代わりに、模擬データを生成
    currentPredictions = {};
    products.forEach(product => {
      currentPredictions[product.商品ID] = Math.floor(Math.random() * 50) + 10;
    });

    // 画面上のAI予測数量を更新
    container.querySelectorAll('.ai-prediction').forEach(span => {
      const productId = span.dataset.productId;
      const prediction = currentPredictions[productId] || 0;
      span.textContent = prediction;

      // 手動調整数量も更新
      const manualInput = container.querySelector(`.manual-quantity[data-product-id="${productId}"]`);
      if (manualInput && !manualInput.value) {
        manualInput.value = prediction;
      }
    });
  }

  // 商品検索
  function searchProducts() {
    const searchTerm = container.querySelector('#product-search').value.toLowerCase();
    const selectedCategory = container.querySelector('#category-select').value;

    let filtered = products.filter(product => {
      const matchesSearch = !searchTerm || 
        (product.商品名 && product.商品名.toLowerCase().includes(searchTerm)) ||
        (product.商品コード && product.商品コード.toLowerCase().includes(searchTerm));

      const matchesCategory = !selectedCategory || product.商品カテゴリID === selectedCategory;

      return matchesSearch && matchesCategory && product.有効フラグ;
    });

    renderProductList(filtered);
  }

  // 初期描画
  renderStoreOptions();
  renderCategoryOptions();
  renderProductList();
  renderOrderItems();

  // イベントリスナー

  // 店舗選択時にAI予測を取得
  container.querySelector('#store-select').addEventListener('change', async (e) => {
    if (e.target.value) {
      await fetchAIPredictions(e.target.value);
    }
  });

  // カテゴリ選択・商品検索
  container.querySelector('#category-select').addEventListener('change', searchProducts);
  container.querySelector('#product-search').addEventListener('input', searchProducts);

  // 手動調整数量の入力検証
  container.addEventListener('input', (e) => {
    if (e.target.classList.contains('manual-quantity')) {
      const value = parseInt(e.target.value);
      if (value < 0) {
        showError('手動調整数量は0以上の値を入力してください');
        e.target.style.borderColor = '#ff6b6b';
      } else {
        e.target.style.borderColor = '';
      }
    }
  });

  // 発注日・納期の検証
  container.querySelector('#order-date').addEventListener('change', (e) => {
    const orderDate = new Date(e.target.value);
    const today = new Date();
    today.setHours(0, 0, 0, 0);

    if (orderDate < today) {
      showError('発注日に過去の日付は設定できません');
      e.target.value = today.toISOString().split('T')[0];
    }
  });

  container.querySelector('#delivery-date').addEventListener('change', (e) => {
    const deliveryDate = new Date(e.target.value);
    const orderDate = new Date(container.querySelector('#order-date').value);

    if (deliveryDate < orderDate) {
      showError('納期は発注日以降の日付を設定してください');
      e.target.value = '';
    }
  });

  // 予測根拠表示
  container.querySelector('#btn-prediction-basis').addEventListener('click', () => {
    const area = container.querySelector('#prediction-basis-area');
    const content = container.querySelector('#prediction-basis-content');

    if (area.classList.contains('hidden')) {
      content.innerHTML = `
        <div style="margin-bottom: 12px;">
          <strong>予測要因分析:</strong><br>
          • 過去3ヶ月の売上トレンド: +15%<br>
          • 季節性要因: 春季需要増加 (+8%)<br>
          • 天候要因: 晴天予報による外出増加 (+5%)<br>
          • イベント要因: 近隣イベント開催 (+12%)
        </div>
        <div>
          <strong>予測精度:</strong> 87%<br>
          <strong>信頼区間:</strong> ±10%
        </div>
      `;
      area.classList.remove('hidden');
    } else {
      area.classList.add('hidden');
    }
  });

  // 在庫状況確認
  container.querySelector('#btn-stock-check').addEventListener('click', () => {
    alert('在庫状況: 全商品の在庫データを最新に更新しました。\n在庫不足商品: 3件\n適正在庫商品: 47件');
  });

  // 過去実績参照
  container.querySelector('#btn-past-records').addEventListener('click', () => {
    alert('過去実績データ:\n• 先月売上: 前年同月比 +12%\n• 平均発注サイクル: 3.2日\n• 在庫回転率: 8.5回/月');
  });

  // イベントデリゲーション
  container.addEventListener('click', async (e) => {
    // 商品を発注リストに追加
    const addBtn = e.target.closest('.add-to-order');
    if (addBtn) {
      const productId = addBtn.dataset.productId;
      const product = products.find(p => p.商品ID === productId);
      const quantityInput = container.querySelector(`.manual-quantity[data-product-id="${productId}"]`);
      const quantity = parseInt(quantityInput.value) || 0;

      if (quantity <= 0) {
        showError('発注数量を正しく入力してください');
        return;
      }

      // 既存アイテムをチェック
      const existingIndex = orderItems.findIndex(item => item.商品ID === productId);
      if (existingIndex >= 0) {
        orderItems[existingIndex].発注数量 = quantity;
      } else {
        orderItems.push({
          商品ID: productId,
          商品コード: product.商品コード,
          商品名: product.商品名,
          発注数量: quantity,
          単価: product.単価 || 0
        });
      }

      renderOrderItems();
    }

    // 発注リストから商品を削除
    const removeBtn = e.target.closest('.remove-from-order');
    if (removeBtn) {
      const productId = removeBtn.dataset.productId;
      orderItems = orderItems.filter(item => item.商品ID !== productId);
      renderOrderItems();
    }
  });

  // 発注書作成
  container.querySelector('#btn-create-order').addEventListener('click', async () => {
    const storeId = container.querySelector('#store-select').value;
    const orderDate = container.querySelector('#order-date').value;
    const deliveryDate = container.querySelector('#delivery-date').value;

    // バリデーション
    if (!storeId) {
      showError('店舗を選択してください');
      return;
    }

    if (!orderDate) {
      showError('発注日付を入力してください');
      return;
    }

    if (!deliveryDate) {
      showError('納期を指定してください');
      return;
    }

    if (orderItems.length === 0) {
      showError('発注する商品を選択してください');
      return;
    }

    // 発注データを保存
    try {
      for (const item of orderItems) {
        const orderData = {
          店舗ID: storeId,
          商品ID: item.商品ID,
          発注日: orderDate + 'T00:00:00Z',
          納期予定日: deliveryDate + 'T00:00:00Z',
          発注数量: item.発注数量,
          発注単価: item.単価,
          発注金額: item.発注数量 * item.単価,
          発注方法: '手動発注',
          発注ステータス: '発注済',
          仕入先ID: '00000000-0000-0000-0000-000000000001',
          自動発注フラグ: false,
          作成者ID: '00000000-0000-0000-0000-000000000001',
          更新者ID: '00000000-0000-0000-0000-000000000001'
        };

        await window.aivicApi.save(7, orderData); // 発注データテーブル
      }

      alert('発注書を作成しました');
      window.showScreen('scr-1778591852463'); // 発注管理画面に遷移

    } catch (error) {
      showError('発注書の作成に失敗しました');
    }
  });
}
